package schemagen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"html"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
	"unicode"
)

const header = "// Code generated by schemagen from the schema.org vocabulary. DO NOT EDIT.\n\npackage schema\n\n"

// Generate writes the generated files for package schema into dir. It
// fails if a generated name clashes with a name declared in the
// handwritten files already in dir, or with another generated name.
func Generate(v *Vocab, dir string) error {
	names, err := handwrittenNames(dir)
	if err != nil {
		return err
	}
	g := &generator{v: v, taken: map[string]string{}, enumOnly: v.EnumOnlyProps()}
	for _, n := range names {
		g.taken[n] = "handwritten code"
	}
	files := map[string]func() (string, error){
		"props_gen.go":    g.props,
		"types_gen.go":    g.types,
		"enums_gen.go":    g.enums,
		"registry_gen.go": g.registry,
	}
	order := []string{"props_gen.go", "types_gen.go", "enums_gen.go", "registry_gen.go"}
	out := map[string][]byte{}
	for _, name := range order {
		src, err := files[name]()
		if err != nil {
			return err
		}
		formatted, err := format.Source([]byte(header + src))
		if err != nil {
			return fmt.Errorf("schemagen: format %s: %w", name, err)
		}
		out[name] = formatted
	}
	for _, name := range order {
		if err := os.WriteFile(filepath.Join(dir, name), out[name], 0o644); err != nil {
			return err
		}
	}
	return nil
}

// Unplaced returns properties that no generated struct can carry, because
// every domain they list is a value type. Use Node.Extra for them.
func (v *Vocab) Unplaced() []string {
	placed := map[string]bool{}
	for _, c := range v.StructClasses() {
		for _, p := range v.Applicable(c) {
			placed[p] = true
		}
	}
	var out []string
	for name := range v.Props {
		if !placed[name] {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

type generator struct {
	v        *Vocab
	taken    map[string]string // Go identifier -> what declared it
	enumOnly map[string]string // property -> the one enumeration it takes
}

func (g *generator) claim(name, by string) error {
	if prev, ok := g.taken[name]; ok {
		return fmt.Errorf("schemagen: identifier %s from %s clashes with %s", name, by, prev)
	}
	g.taken[name] = by
	return nil
}

func (g *generator) props() (string, error) {
	var b strings.Builder
	for _, class := range g.v.StructClasses() {
		props := g.v.BlockProps(class)
		if len(props) == 0 {
			continue
		}
		name := goType(class) + "Props"
		if err := g.claim(name, "props block of "+class); err != nil {
			return "", err
		}
		fmt.Fprintf(&b, "// %s holds the properties that only %s defines. Every type\n// inheriting from %s embeds it.\n", name, class, class)
		fmt.Fprintf(&b, "type %s struct {\n", name)
		for _, p := range props {
			g.field(&b, p)
		}
		b.WriteString("}\n\n")
	}
	for _, p := range g.v.TraitProps() {
		name := goName(p) + "Trait"
		if err := g.claim(name, "trait for "+p); err != nil {
			return "", err
		}
		fmt.Fprintf(&b, "// %s holds %s, which %s share.\n", name, p, joinNames(g.v.Props[p].Domains))
		fmt.Fprintf(&b, "type %s struct {\n", name)
		g.field(&b, p)
		b.WriteString("}\n\n")
	}
	return b.String(), nil
}

func (g *generator) field(b *strings.Builder, prop string) {
	p := g.v.Props[prop]
	enum, enumOnly := g.enumOnly[prop]
	summary := summarize(cleanComment(p.Comment), 300)
	switch {
	case enumOnly:
		summary += " Allowed: " + enum + " members, " + enum + " nodes, or a Ref."
	case len(p.Ranges) > 0:
		summary += " Expected: " + strings.Join(p.Ranges, ", ") + "."
	}
	if p.Part != "" {
		summary += " Part of " + p.Part + ".schema.org."
	}
	writeDoc(b, "\t", goName(prop)+": "+summary)
	if len(p.SupersededBy) > 0 {
		b.WriteString("\t//\n")
		writeDoc(b, "\t", "Deprecated: superseded by "+strings.Join(p.SupersededBy, ", ")+".")
	}
	typ := "Values"
	if enumOnly {
		typ = goType(enum) + "List"
	}
	fmt.Fprintf(b, "\t%s %s `json:\"%s,omitempty\"`\n", goName(prop), typ, prop)
}

func (g *generator) types() (string, error) {
	var b strings.Builder
	for _, class := range g.v.StructClasses() {
		name := goType(class)
		if err := g.claim(name, "type "+class); err != nil {
			return "", err
		}
		plan := g.v.Plan(class)
		if err := g.checkFields(class, plan); err != nil {
			return "", err
		}
		cl := g.v.Classes[class]
		doc := name + " is the schema.org type " + class + ", https://schema.org/" + class + "."
		writeDoc(&b, "", doc)
		if c := summarize(cleanComment(cl.Comment), 400); c != "" {
			b.WriteString("//\n")
			writeDoc(&b, "", c)
		}
		if cl.Part != "" {
			b.WriteString("//\n")
			writeDoc(&b, "", "Part of "+cl.Part+".schema.org.")
		}
		if len(cl.SupersededBy) > 0 {
			b.WriteString("//\n")
			writeDoc(&b, "", "Deprecated: superseded by "+strings.Join(cl.SupersededBy, ", ")+".")
		}
		fmt.Fprintf(&b, "type %s struct {\n\tNode\n", name)
		for _, blk := range plan.Blocks {
			fmt.Fprintf(&b, "\t%sProps\n", goType(blk))
		}
		for _, t := range plan.Traits {
			fmt.Fprintf(&b, "\t%sTrait\n", goName(t))
		}
		b.WriteString("}\n\n")
		fmt.Fprintf(&b, "func (v %s) MarshalJSON() ([]byte, error) {\n\ttype plain %s\n\tv.Type = v.Type.OrDefault(%q)\n\treturn EncodeNode(plain(v), v.Extra)\n}\n\n", name, name, class)
		fmt.Fprintf(&b, "// Ref returns a reference to v by its @id.\nfunc (v %s) Ref() Ref { return Ref{Type: v.Type.OrDefault(%q), ID: v.ID} }\n\n", name, class)
	}
	return b.String(), nil
}

// checkFields makes sure no two embedded fields promote the same Go name,
// which would make encoding/json drop both silently.
func (g *generator) checkFields(class string, plan Plan) error {
	seen := map[string]string{"Type": "Node", "ID": "Node", "Extra": "Node", "Node": "embed", "MarshalJSON": "method", "Ref": "method"}
	add := func(name, by string) error {
		if prev, ok := seen[name]; ok {
			return fmt.Errorf("schemagen: %s: field %s from %s clashes with %s", class, name, by, prev)
		}
		seen[name] = by
		return nil
	}
	for _, blk := range plan.Blocks {
		if err := add(goType(blk)+"Props", "embed"); err != nil {
			return err
		}
		for _, p := range g.v.BlockProps(blk) {
			if err := add(goName(p), blk+"Props"); err != nil {
				return err
			}
		}
	}
	for _, t := range plan.Traits {
		if err := add(goName(t)+"Trait", "embed"); err != nil {
			return err
		}
		if err := add(goName(t), goName(t)+"Trait"); err != nil {
			return err
		}
	}
	return nil
}

func (g *generator) enums() (string, error) {
	var b strings.Builder
	ranges := g.v.RangeEnums()
	structs := g.v.StructClasses()
	for _, e := range ranges {
		iface, list := goType(e)+"Enum", goType(e)+"List"
		for _, n := range []string{iface, list} {
			if err := g.claim(n, "enumeration "+e); err != nil {
				return "", err
			}
		}
		writeDoc(&b, "", iface+" is a value for a property that takes only "+e+": one of its members, a member of a sub-enumeration, an "+e+" node, or a Ref.")
		fmt.Fprintf(&b, "type %s interface {\n\tValue\n\tis%s()\n}\n\n", iface, iface)
		writeDoc(&b, "", list+" holds the values of a property that takes only "+e+". One value encodes as a scalar, more than one as an array.")
		fmt.Fprintf(&b, "type %s []%s\n\n", list, iface)
		fmt.Fprintf(&b, "func (l %s) MarshalJSON() ([]byte, error) { return marshalList(l) }\n\n", list)
		fmt.Fprintf(&b, "func (Ref) is%s() {}\n\n", iface)
		for _, c := range structs {
			if slices.Contains(g.v.Ancestors(c), e) {
				fmt.Fprintf(&b, "func (%s) is%s() {}\n", goType(c), iface)
			}
		}
		b.WriteString("\n")
	}

	// One member type per enumeration (or per set of enumerations, for a
	// member of several). It satisfies the Enum interface of every range
	// enumeration it inherits from.
	groups := map[string][]string{}
	for n, m := range g.v.Members {
		groups[memberType(m.Enums)] = append(groups[memberType(m.Enums)], n)
	}
	typeNames := make([]string, 0, len(groups))
	for t := range groups {
		typeNames = append(typeNames, t)
	}
	sort.Strings(typeNames)
	for _, t := range typeNames {
		members := groups[t]
		sort.Strings(members)
		enums := g.v.Members[members[0]].Enums
		if err := g.claim(t, "member type of "+strings.Join(enums, ", ")); err != nil {
			return "", err
		}
		writeDoc(&b, "", t+" is a member of "+joinNames(enums)+". It encodes as its https://schema.org/ URL.")
		fmt.Fprintf(&b, "type %s string\n\n", t)
		fmt.Fprintf(&b, "func (%s) isValue() {}\n\n", t)
		fmt.Fprintf(&b, "func (m %s) MarshalJSON() ([]byte, error) { return EnumMember(m).MarshalJSON() }\n\n", t)
		for _, e := range ranges {
			for _, own := range enums {
				if slices.Contains(g.v.Ancestors(own), e) {
					fmt.Fprintf(&b, "func (%s) is%sEnum() {}\n", t, goType(e))
					break
				}
			}
		}
		b.WriteString("\nconst (\n")
		for _, n := range members {
			m := g.v.Members[n]
			name := goType(n)
			if err := g.claim(name, "enumeration member "+n); err != nil {
				return "", err
			}
			doc := name + " is a member of " + strings.Join(m.Enums, ", ") + "."
			if c := summarize(cleanComment(m.Comment), 200); c != "" {
				doc += " " + c
			}
			writeDoc(&b, "\t", doc)
			fmt.Fprintf(&b, "\t%s %s = %q\n", name, t, n)
		}
		b.WriteString(")\n\n")
	}
	return b.String(), nil
}

// memberType names the Go type of a member of the given enumerations:
// ItemAvailabilityMember, or MedicalImagingTechniqueAndMedicalSpecialtyMember
// for a member of two.
func memberType(enums []string) string {
	parts := make([]string, len(enums))
	for i, e := range enums {
		parts[i] = goType(e)
	}
	return strings.Join(parts, "And") + "Member"
}

func (g *generator) registry() (string, error) {
	for _, n := range []string{"constructors", "typeNames"} {
		if err := g.claim(n, "registry"); err != nil {
			return "", err
		}
	}
	classes := g.v.StructClasses()
	var b strings.Builder
	b.WriteString("var constructors = map[string]func() Value{\n")
	for _, c := range classes {
		fmt.Fprintf(&b, "\t%q: func() Value { return &%s{} },\n", c, goType(c))
	}
	b.WriteString("}\n\nvar typeNames = []string{\n")
	for _, c := range classes {
		fmt.Fprintf(&b, "\t%q,\n", c)
	}
	b.WriteString("}\n")
	return b.String(), nil
}

// handwrittenNames lists top-level identifiers declared in the
// non-generated, non-test Go files of dir.
func handwrittenNames(dir string) ([]string, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return nil, err
	}
	var names []string
	fset := token.NewFileSet()
	for _, f := range files {
		base := filepath.Base(f)
		if strings.HasSuffix(base, "_gen.go") || strings.HasSuffix(base, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, f, nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, err
		}
		for _, d := range file.Decls {
			switch d := d.(type) {
			case *ast.FuncDecl:
				if d.Recv == nil {
					names = append(names, d.Name.Name)
				}
			case *ast.GenDecl:
				for _, s := range d.Specs {
					switch s := s.(type) {
					case *ast.TypeSpec:
						names = append(names, s.Name.Name)
					case *ast.ValueSpec:
						for _, n := range s.Names {
							names = append(names, n.Name)
						}
					}
				}
			}
		}
	}
	return names, nil
}

var initialisms = map[string]string{"Url": "URL", "Id": "ID"}

// GoName returns the Go field name generated for a schema.org property.
func GoName(prop string) string { return goName(prop) }

// goName turns a schema.org property name into an exported Go name:
// sameAs -> SameAs, contentUrl -> ContentURL.
func goName(s string) string {
	words := splitCamel(s)
	for i, w := range words {
		w = upperFirst(w)
		if r, ok := initialisms[w]; ok {
			w = r
		}
		words[i] = w
	}
	return fixDigit(strings.Join(words, ""))
}

// GoType returns the Go type name generated for a schema.org class.
func GoType(class string) string { return goType(class) }

// goType turns a schema.org class or member name into a Go name. Names
// keep their schema.org spelling; a leading digit gets an X prefix.
func goType(s string) string { return fixDigit(s) }

func fixDigit(s string) string {
	if s != "" && unicode.IsDigit(rune(s[0])) {
		return "X" + s
	}
	return s
}

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// splitCamel splits at each lower-to-upper or digit-to-upper change.
// Runs of capitals stay together: propertyID -> property, ID.
func splitCamel(s string) []string {
	var words []string
	start := 0
	for i := 1; i < len(s); i++ {
		prev, cur := rune(s[i-1]), rune(s[i])
		if unicode.IsUpper(cur) && (unicode.IsLower(prev) || unicode.IsDigit(prev)) {
			words = append(words, s[start:i])
			start = i
		}
	}
	return append(words, s[start:])
}

var (
	reWiki  = regexp.MustCompile(`\[\[([^\]]+)\]\]`)
	reLink  = regexp.MustCompile(`\[([^\]]+)\]\([^)]*\)`)
	reTag   = regexp.MustCompile(`<[^>]+>`)
	reEsc   = regexp.MustCompile(`\\([\\_*\[\]()#.-])`)
	reSpace = regexp.MustCompile(`\s+`)
)

// cleanComment strips the wiki links, markdown and HTML that schema.org
// comments contain.
func cleanComment(s string) string {
	s = strings.ReplaceAll(s, `\n`, " ")
	s = reWiki.ReplaceAllString(s, "$1")
	s = reLink.ReplaceAllString(s, "$1")
	s = reTag.ReplaceAllString(s, "")
	s = reEsc.ReplaceAllString(s, "$1")
	s = html.UnescapeString(s)
	s = reSpace.ReplaceAllString(s, " ")
	return strings.TrimSpace(s)
}

// summarize cuts s to at most max bytes, at a sentence end when it can.
func summarize(s string, max int) string {
	if len(s) <= max {
		return s
	}
	cut := s[:max]
	if i := strings.LastIndex(cut, ". "); i > max/3 {
		return cut[:i+1]
	}
	if i := strings.LastIndex(cut, " "); i > 0 {
		cut = cut[:i]
	}
	return strings.TrimRight(cut, ",;:") + "..."
}

func writeDoc(b *strings.Builder, indent, s string) {
	for _, line := range wrap(s, 76) {
		b.WriteString(indent + "// " + line + "\n")
	}
}

func wrap(s string, width int) []string {
	var lines []string
	var cur bytes.Buffer
	for _, w := range strings.Fields(s) {
		if cur.Len() > 0 && cur.Len()+1+len(w) > width {
			lines = append(lines, cur.String())
			cur.Reset()
		}
		if cur.Len() > 0 {
			cur.WriteByte(' ')
		}
		cur.WriteString(w)
	}
	if cur.Len() > 0 {
		lines = append(lines, cur.String())
	}
	return lines
}

func joinNames(names []string) string {
	switch len(names) {
	case 0:
		return ""
	case 1:
		return names[0]
	}
	return strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
}
